// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.productivity.alarm/** * NOUS — Alarm Data Models (Module 14 v1.2 — Step 14.1). * * Data structures for alarms + timers. *//** A scheduled alarm (REAL AlarmManager.setAlarmClock). */data class AlarmInfo(    val id: String,    val label: String,    val triggerAtMs: Long,    val type: AlarmType,    val isEnabled: Boolean = true,    val createdAtMs: Long = System.currentTimeMillis(),) {    /** Time remaining until alarm fires (milliseconds). */    fun remainingMs(): Long = (triggerAtMs - System.currentTimeMillis()).coerceAtLeast(0)    /** True if the alarm has already fired (past trigger time). */    val hasFired: Boolean get() = System.currentTimeMillis() >= triggerAtMs    /** Human-readable time string (e.g., "7:00 AM tomorrow"). */    val displayTime: String        get() {            val sdf = java.text.SimpleDateFormat("h:mm a, EEE", java.util.Locale.getDefault())            return sdf.format(java.util.Date(triggerAtMs))        }}/** Type of alarm/timer. */enum class AlarmType(val displayName: String) {    /** Alarm at a specific time (e.g., "7 AM tomorrow"). */    ALARM("Alarm"),    /** Timer for a duration (e.g., "10 minutes"). */    TIMER("Timer"),}/** Result of alarm operations (sealed class for async returns). */sealed interface AlarmResult<out T> {    data class Success<T>(val data: T, val spokenMessage: String) : AlarmResult<T>    data class Failure(val error: String, val spokenMessage: String) : AlarmResult<Nothing>    data class NeedsPermission(val permissions: List<String>, val spokenMessage: String) : AlarmResult<Nothing>}// ═══════════════════════════════════════════════════════════════════════════// Alarm Store (in-memory for v1 — Room DB in production)// ═══════════════════════════════════════════════════════════════════════════/** * Alarm Store — manages alarm state (active alarms list). * * Production: Room database (encrypted via SQLCipher from Module 12). * Current: In-memory map (sufficient for v1 — alarms rescheduled on reboot). */class AlarmStore {    private val alarms = mutableMapOf<String, AlarmInfo>()    /** Store a new alarm. */    fun put(alarm: AlarmInfo) {        alarms[alarm.id] = alarm    }    /** Get an alarm by ID. */    fun getById(id: String): AlarmInfo? = alarms[id]    /** Get all active alarms. */    fun getAllActive(): List<AlarmInfo> = alarms.values.filter { it.isEnabled && !it.hasFired }    /** Get the next alarm to fire (earliest trigger time). */    fun getNextActive(): AlarmInfo? = getAllActive().minByOrNull { it.triggerAtMs }    /** Delete an alarm by ID. */    fun deleteById(id: String): Boolean = alarms.remove(id) != null    /** Mark an alarm as disabled (fired). */    fun markAsFired(id: String) {        alarms[id]?.let { alarms[id] = it.copy(isEnabled = false) }    }    /** Get count of active alarms. */    fun activeCount(): Int = getAllActive().size    /** Clear all alarms. */    fun clear() = alarms.clear()}// ═══════════════════════════════════════════════════════════════════════════// FTS5 Utilities// ═══════════════════════════════════════════════════════════════════════════/** * FTS5 query sanitization utility (per strategy v1.2 §"Polish 5"). * * FTS5 treats certain characters as operators (:, -, *, ", (, )). * This utility wraps user queries in double quotes for safe phrase matching. */object Fts5Utils {    /**     * Escape a user query for FTS5 MATCH (phrase search).     *     * Wraps the entire query in double quotes, escaping internal quotes by doubling.     */    fun escapeFts5Query(query: String): String {        if (query.isBlank()) return "\"\""        val escaped = query.replace("\"", "\"\"")        return "\"$escaped\""    }    /**     * Build a prefix search query (for "starts with" search).     *     * Example: "med" → "med*" (matches "medicine", "medical").     */    fun buildPrefixQuery(query: String): String {        val sanitized = query.trim().replace(Regex("[:*\"()]"), " ")        if (sanitized.isBlank()) return "\"\""        return "$sanitized*"    }}// ═══════════════════════════════════════════════════════════════════════════// Markdown to Text Parser// ═══════════════════════════════════════════════════════════════════════════/** * Markdown to plain text converter (per strategy v1.1 §"Improvement 3"). * * Strips Markdown formatting before sending to TTS — TTS can't read Markdown * (e.g., "# Heading" would be spoken as "Hash Heading"). */object MarkdownToTextParser {    /**     * Strip Markdown formatting and return plain text.     */    fun stripMarkdown(markdown: String): String {        return markdown            .replace(Regex("^#{1,6}\\s+"), "")          // # Heading → Heading            .replace(Regex("\\*\\*(.+?)\\*\\*"), "$1")  // **bold** → bold            .replace(Regex("\\*(.+?)\\*"), "$1")         // *italic* → italic            .replace(Regex("`(.+?)`"), "$1")             // `code` → code            .replace(Regex("\\[(.+?)\\]\\(.+?\\)"), "$1") // [link](url) → link            .replace(Regex("^[-*+]\\s+", RegexOption.MULTILINE), "") // - bullet → bullet            .replace(Regex("^>\\s+", RegexOption.MULTILINE), "")    // > quote → quote            .replace(Regex("---+"), "")                  // --- separator → remove            .replace(Regex("\\n{3,}"), "\n\n")           // Max 2 consecutive newlines            .trim()    }}